NAME = 'PohnOld: Old Public Domain Pohnpeian Bible'
BOOK = 'Romans'

CHAPTERS = {
    1: {
        1: 'PAULUS ladun Iesus Kristus men, me paeker, en wiala wanporon amen, me katoror ong papa rongamau en Kot,',
        2: 'Me a kotin kopekidor sapwilim a saukop akan nan kisin likau saraui kan.',
        3: 'Duen sapwilim a Ol me kisan kadaudok en Dawid ni tiak en pali uduk,',
        4: 'O me kadede kidar, me a Sapwilim en Kot a manaman, duen a kotin iasadar sang ren me melar akan ki Ngen saraui, Iesus Kristus atail Kaun,',
        5: 'Me kit ale sanger mak o koa en wanporon, pwen padaki ong men liki kan karos ni mar a, pwe irail en poson o peik,',
        6: 'Pwe komail pil kisan irail, me paeker dong Iesus Kristus.',
        7: 'Komail karos kompoke pan Kot, me paeker me saraui kan, me mimi Rom mak o popol sang ren Kot Sam atail o Kaun Iesus Kristus en mi re omail!',
        8: 'Iet kaieu, i kin kapinga ai Kot ki Iesus Kristus pweki komail karos; pwe omail poson me kalok sili lel penang sap karos.',
        9: 'Pwe Kot, me i kin papa ong ni ngen i ni ai padapadaki wei rongamau en sapwilim a Ol, me saunkadede pai, me i kin tamataman kin komail ansau karos, ngidingid ni ai kapakap akan.',
        10: 'Ngidingideki ansau karos, ma i sota pan kak pwarala re omail, ma iduen kupur en Kot.',
        11: 'Pwe i inong iong udial komail, pwe i en katungole kin komail ekis pwais ngenin, pwe komail en tinainda.',
        12: 'Pwe i en kasarloleid re omail, pweki atail poson ta ieu.',
        13: 'Ari, ri ai ol akan, i sota men, me komail en sasa duen ai kileledier pan pak toto, en pwar wong komail, ap saik pisoki ong, pwen diar ekis wan ai dodok re omail, dueta ren wei tei kan.',
        14: 'Pwe ngai me pwaipwand ong men Krik o men liki kan, o ong me lolekong o me so lolekong kan.',
        15: 'Pwe duen a pan kak pai, i men pil padaki ong komail men Rom rongamau.',
        16: 'Pwe i sota kin namenok ki rongamau, pwe i manaman en Kot, me kin kamaurela me poson akan karos, Sus oko mas, ap pil men Krik.',
        17: 'Pwe i me kin kasansaleda pung en Kot, me kin pwili sang poson, pwen poson duen a intingidier: Me pung o pan memaureki poson;',
        18: 'Pwe ongiong en Kot pan sansaleda sang nanlang ong me doo sang Kot akan o me sapung en aramas akan, me kin kawela melel ni arail sapung.',
        19: 'Pwe duen me pwarada sang ren Kot me sansal ong irail, pwe Kot me kotin kasansale ong irail,',
        20: 'Pwe meakan me so sansal duen i, iet akan, a manaman soutuk o pil duen a udan Kot sang ni ansaun sappa wiauier, kin sansal kida sapwilim a dodok kan, pwe solar pekid parail:',
        21: 'Pweki irail asadar Kot, a re sota wauneki i duen me kon ong Kot pil sota masak tol a, a re aklemai ong i, mongiong sapung arail ap rotorotalar.',
        22: 'Irail akereki pein irail ap lamponlar.',
        23: 'Irail kawukilar lingan en Kot me so kak mor pasang, ong mom en aramas me kin mor pasang o mom en manpir akai, o man aluki pa, o man korop akan.',
        24: 'I me Kot kotin mueide kila irail, en inong iong kasaminlar mongiong arail ni ar kasautela pein war arail nan pung arail,',
        25: 'Me kawukila melel en Kot ong likam, ap pongi o papa ong dipisou mon Saun wia meakaros, me iasanai potepoteta amen.',
        26: 'Nan i me Kot mueidela kin ir ong inong sued akan, en lel ong arail li akan, en wuki sang ira’rail, kaokaoe ira’rail.',
        27: 'Pil dueta ol akan liki sang iran li, ap kalel nan pung arail; ol asada ol, me so kon, ap pein kapokala nan war arail mangidi en ar wiawia kan.',
        28: 'Nan duen irail kang kataman ong Kot, Kot ap mueidalang irail, en kapitakaila kamom ong wia meakan me sued,',
        29: 'Me dir en sapung karos, morsued, norok kapwa, sempok, dir en peirin, lolap, akamai, widing, weid, lidu mongin,',
        30: 'Pil en pan moli, likinekine, kasenta Kot, kang kapunglol, aklapalap, ponmaso, me kin diar me sued akan, so oke sam ar o in ar,',
        31: 'Lampon, inausopousok, sempok, somak.',
        32: 'Re asa duen kapung pung en Kot, me kin wia mepukat, pan mau ong mela, a kaidin i eta, pwe re pil kin perenki irail, me kin wia mepukat.',
    },
    2: {
        1: 'NAN i sota pakid pa om, aramas amen koe, amen amen me kin kadeikada, pwe ni om kadeikada amen, pein koe me koe kin kariala, pwe koe, me kin kadeikada, kin wiawia me dueta.',
        2: 'A kitail asaer, me kadeik en Kot me melel ong ir, me kin wiada mepukat.',
        3: 'A dadue aramas amen koe, me kin kadeikada, me kin wiewia mepukat, ap wiada dueta, koe kiki ong, me koe pan piti sang kadeik en Kot?',
        4: 'De koe mamaleki kalangan en Kot sapan, o a kanongama o papadake; koe sota asa, me kalangan en Kot kamaterok uk alang kalula?',
        5: 'A koe ni mongiong om me katiwo o kakaluak, me koe ki penang uk ongiong ong ni ran en ongiong o kasansal pan kadeik pung en Kot,',
        6: 'Me pan kotin depuk ong amen amen duen a wiawia kan.',
        7: 'Irail me kin dadaurata ni ar wiawia mau kan o lingan, o indand, o me so kin mor pasang, maur soutuk.',
        8: 'A kamekam o wairok ong irail me katiwo o so oke melel, a me kin oke sapung.',
        9: 'O kanaudok o kalokolok ong aramas karos, me wiadar sued, mas ong Sus akan ap lel ong men Krik.',
        10: 'A lingan, o wau, o popol ong amen amen, me kin wia mau, mas ong Sus akan o pil ong men Krik.',
        11: 'Pwe Kot sota kin lipilipil aramas amen.',
        12: 'Pwe karos me wiada dip likin kapung, pan lokidokila likin kapung, pil karos, me asa kapung, ap wiada dip, pan pakadeikada pan kapung.',
        13: 'Pwe kaidin me rongerong kapung kan pan pung kila mon Kot, a me kin angada kapung pan pung kila.',
        14: 'Pwe ma men liki, me sota arail kapung, ap pil wiawia tiak en kapung sang nan pein irail, iei me irail, me sota arail kapung pein kapung parail.',
        15: 'Me kin kasansaleda wiawia en kapung me intingidier nan mongiong arail, i me insen arail pil kadedeki o ar lamalam, me irail sakara kida de kalole mau ki nan pung arail.',
        16: 'Lao ran o, me Kot pan kotiki ong Iesus en kadeikada dip okiok kan ren aramas akan, duen ai rongamau.',
        17: 'A ma koe adaneki Sus amen, me kin liki kapung o suaiki Kot,',
        18: 'O asada kupur a, o koe pung kila lamalam, ni om padapadaki sang nan kapung,',
        19: 'Koe me lameda, me koe itar ong, en kalua wei me maskun akan, o kamarain pan me rotorot akan,',
        20: 'O saunkaian pan me lampon kan, o saunpadak en kisin seri kan, me asa tiak en lolekong o melel en kapung.',
        21: 'Ari, koe kin kawewe ong amen, ap sota kin kawewe ong pein uk, o koe kin padaki me ren der pirap, a koe kin pirap;',
        22: 'Koe kin inda, me aramas ender kamal, a koe kin kamal? Koe kin suedeki dikedik en ani mal akan, a koe kin pirap me sapwilim en Kot?',
        23: 'Koe kin suaiki kapung, a koe kin kisang Kot waui ni om tiakedi kapung?',
        24: 'Pwe mar en Kot kin mamale kila komail ren men liki kan, duen a intingidier.',
        25: 'Pwe sirkomsais me mau, ma koe angeda kapung; a ma koe tiakedi kapung, om sirkomsais pan sosirkomsais.',
        26: 'Nan i, me sosirkomsais, angada pung en kapung, daduen a sosirkomsais so pan wadok ong i sirkomsais?',
        27: 'Ari, ma me udan sosirkomsais akan pan kapwaiada kapung, re sota pan kadeik uk ada? Pwe koe kin mi pan kisin likau o sirkomsais, ap tiakedi kapung o.',
        28: 'Pwe kaidin i Sus amen, ma pali liki ta, o pil kaidin i sirkomsais, me sirkomsais liki nan uduk eta.',
        29: 'A i Sus amen, me Sus en lole, o i sirkomsais, me mi nan mongiong i, ni ngen e, a kaidin ni inting; me a kapingepa sota mi ren aramas akan pwe ren Kot.',
    },
    3: {
        1: 'ARI, da me Sus akan paieki mon me tei kan de da kadepan sirkomsais?',
        2: 'O me toto, ni song karos; iet kaieu: Masan en Kot akan kanikid ong irail.',
        3: 'A ma akai soposon a pil menda? Pwe ar soposon pan kak kawela kalangan en Kot?',
        4: 'O so! Pwe Kot udan melel, a aramas karos me likam duen a intingidier: Ir eta me pung ni ar masan akan, o komui pan kotin poedi ni ar pakadeikada.',
        5: 'A ma atail sapung kaindinda pung en Kot, da me kitail en inda? Dadue, Kot me pil sapung, pweki a kotin ongiong kida? I kin lokaia ni tiak en aramas.',
        6: 'O so! Pwe ma iduen, Kot pan kak kadeikada sappa?',
        7: 'Pwe ma melel en Kot pwai kida ai likam kan, pwen kalinganada i, menda i pan pakadeikada, dene dipan amen ngai?',
        8: 'A so mau ong duen at indand sued, pwe akai kin inda, me dene kit kin padaki wei: Kitail en wiada me sued, pwen kareda me mau? Nan arail kalokolok me pung.',
        9: 'Iaduen atail pai mau sang arail? Kaidin, pwe se kadededar, me Sus o men Krik karos mi pan dip,',
        10: 'Duen a intingidier: Sota me pung amen, sota amen.',
        11: 'Sota me lolekong amen, sota me kin rapaki Kot.',
        12: 'Karos me sapunglar, irail wiaki eu mamalar, sota meamen, me kin wiada me mau, sota amen.',
        13: 'Tapin wor arail me rasong sousou eu, me saikenta sarep pena, lo arail me re liliapaki, wini en kamela mimi ni oton ngi arail;',
        14: 'Au ar me dir en lalaue o katik,',
        15: 'Nä arail me marara ong kamela aramas;',
        16: 'Nan al arail me dir en sued o mauk;',
        17: 'A al en popol me re sasa;',
        18: 'Re sota kin masak Kot.',
        19: 'A kitail asaer, me kapung o lolok ong, me kin papa kapung pwe au karos en sapaimokid o sappa pon lodi ong kadeik en Kot.',
        20: 'Ari mon Kot sota uduk me pan pung kila a wiawia kapung, pwe kapung me dip kadiarok kidar;',
        21: 'A ansau wet pung en Kot sansaledar likin kapung o kadede kidar kapung o saukop akan.',
        22: 'A pung en Kot me pwili sang poson Iesus Kristus, ap lel ong karos me poson.',
        23: 'Pwe sota lipilipil, karos me wiadar dip o sota kak konodi lingan en Kot.',
        24: 'Irail pan pung kila a mak sapan, pweki en Kristus Iesus a kotin dore kitail lar,',
        25: 'Me Kot kotin kasansaledar en wiala mol en kalangan ni poson nt’a, pwen kasansaleda a pung ni a kotin lapwada dip en mas akan, me mier pan papadake en Kot.',
        26: 'A ansau wet a kotin kadededa a pung. Ieteten, me pein i me pung, ap pan kotin kapungala karos me poson Iesus.',
        27: 'Ari, ia men suaiki? A lokidokilar! Ren kapung da? En wiawia kan? Kaidin, a ren kapung en poson.',
        28: 'Ari, iet me se inda: Aramas en pung kila poson a kaidin wiawia en kapung kan.',
        29: 'De Kot en men Sus akan arail Kot eta? Kaidin pil Kot en men liki kan? Ei melel, pil en men liki!',
        30: 'Ari, Kot me ta men, me kin kapung kila me sirkomsais akan pweki poson, pil sosirkomsais akan pweki poson.',
        31: 'Iaduen, kitail kin tiakedi kapung pweki poson? O so! Pwe kitail kin kapwaiada kapung o.',
    },
    4: {
        1: 'ARI, da me kitail en inda duen Apraam sam atail ni pali uduk, da me a diaradar?',
        2: 'Pwe ma Apraam pung kilar a wiawia kan, nan a men suaiki mia, a kaidin mon Kot.',
        3: 'Pwe da me kisin likau masanier? Apraam poson Kot, o i me wadok ong i kapunga pa.',
        4: 'A me kin keleki a wiawia kan, nan pwain a pan wad ong i nin tiak en kusoned a kaidin ni mak.',
        5: 'A me sota kin keleki a wiawia kan, ap poson i, me kin kapungala me doo sang Kot akan, nan a poson me wadok ong i kapunga pa i.',
        6: 'Duen Dawid kapaiaki aramas amen, me Kot kotin kapungala likin a wiawia kan:',
        7: 'Meid pai, me ar sapung kan lapwadar, o me dip ar akan pwaipwaidier!',
        8: 'Meid pai ol o, me Kaun o solar pan kapokoki ong dip a!',
        9: 'Ari, me sirkomsais eta, me pai wet kin ko ong, de a pil itar ong me sosirkomsais? Pwe kit me indada: En Apraam a poson me wadok ong i kapunge pa.',
        10: 'Ari, iaduen a wadok ong i? Ni a sirkomsaiselar de ni a sosirkomsaiselar? Kaidin ni sirkomsais, pwe ni a sosirkomsais.',
        11: 'A a aleer kilel en sirkomsais, men kadede a pung kilar poson, me a anekier ni a sosirkomsais, pwen wiala sam en me poson ap sosirkomsais akan karos, pwe pung wet en pil wadok ong irail.',
        12: 'O pil wiala sam en me sirkomsais akan. A kaidin arail me sirkomsais akan eta, pwe pil en irail, me aluki poson ota, me mi ren sam atail Apraam ni a sosirkomsais.',
        13: 'Pwe kaidin ki kapung o me Apraam o kadaudok a aleer inau o, me a pan sosoki sappa, a ki poson pung.',
        14: 'Pwe ma irail, me men kapwaiada kapung o, pan ale soso, nan poson me mal kot, o inau olar.',
        15: 'Pwe kapung o kin kareda ongiong, pwe ma sota kapung, a pil sota sapung.',
        16: 'I me pung pan tapi sang ni poson, pwe karos en tapi sang mak; o inau ong kadaudok o en tengeteng. A kaidin ir eta, me mi pan kapung o, pwe pil karos, me mi pan poson en Apraam, me sam en kitail karos.',
        17: 'Duen a intingidier: I wia kin uk alar sam en wein sappa toto mon Kot, me a poson me kin kamaureda me melar akan o molipei ir, me saikenta mia, pwen miala.',
        18: 'I me poson, ap sota kaporopor mia, pwen wiala sam en wein sappa toto, duen a lokido: Nan iduen kadaudok om.',
        19: 'Ap sota luetalar ni a poson o so lamelame, me war a melar, pwe a koren iong saunpar epuki; pil sota lamelame war en Sara a melar.',
        20: 'Pwe a sota peikasaleki inau en Kot ki soposon, a a kakairida ni poson, o i me a kin kapingaki Kot.',
        21: 'A asa melelia, me i kotin inauki ong i, a pan kotin kapwaiada.',
        22: 'Nan i wadok ong i kapunga pa.',
        23: 'Mepukat sota intingidier pweki i eta, me a wadok ong i mepukat,',
        24: 'A pil pweki kitail, me a pan wadok ong, ma kitail pan poson i, me kotin kaiasadar Iesus atail Kaun sang ren me melar akan.',
        25: 'Pwe i me pangalar pweki dip atail, o a kotin iasadar pwen kapung patail.',
    },
    5: {
        1: 'KITAIL ari pung kilar poson, ap popol ren Kot, pweki atail Kaun Iesus Kristus,',
        2: 'Me kotin kasamo kitail ki poson ong mak wet, me kitail aleer, ap kaporopor o suaiki lingan en Kot,',
        3: 'A kaidin i eta, pwe kitail pil suaiki at apwal akan, pwe kitail asa, me at apwal akan kin kareda kanongama;',
        4: 'A kanongama kin kareda kakairida, a kakairida kin kareda kaporopor;',
        5: 'A kaporopor sota kin kanamenokala, pwe limpok en Kot me wudokidi ong nan mongiong atail ki Ngen saraui, me kitail aleer.',
        6: 'Pwe ni atail luet Kristus mata kin kitail, me doo sang Kot akan ni ansau me kileledier.',
        7: 'Pwe iaduen, amen pan mekila me pung amen? Ele pweki me mau amen, me amen pan mekila.',
        8: 'A Kot kotin kasansaleda a limpok ong kitail ni en Kristus a mata kin kitail lar, ni ansaun atail dipan.',
        9: 'Melel kaualap, ansau wet kitail kapung kilar nta; kitail ap kamaur kila i sang ni ongiong.',
        10: 'A ma kitail kalolamaui ong Kot ki en sapwilim a Ol a matala ni atail imwintiti, nan melel kaualap murin atail kalolamaui kitail pan dorela ki a ieias,',
        11: 'A kaidin i eta, pwe kitail pil suaiki Kot ren atail Kaun Iesus Kristus, me kitail paieki tom patail.',
        12: 'Ari, duen aramas ta men, me dip tapiki dong sappa, ap tialang mela, o mela lel penang aramas akan karos, pwe karos me wiadar dip,',
        13: 'Pwe dip mi nan sappa mon kapung, a sota kapung pan dip, ma sota kapung,',
        14: 'Ari so, mela wiauiada sang Adam lel Moses, pil ren me so wiadar dip laud dueta sapung en Adam, iei me mom en me pan pwarado.',
        15: 'A pai en mak kaidin dueta dip, pwe ma dip en me ta men me toto mekila, nan melel kaualap mak en Kot o pai en mak sang ren aramas ta men Iesus Kristus itar ong me toto.',
        16: 'A pai o kaidin dueta met, me wiauier ren amen, me wiadar dip, pwe kadeik o tapi sanger me ta men, pwen kalokolok, a pai en mak o kin lapwada dip toto, pwen pungala.',
        17: 'Pwe ma dip en me ta men mela poekidier, nan melel kaualap, irail me pan ale mak o pai en pung, pan poedi o mamaureki me ta men: Iesus Kristus.',
        18: 'A duen dip en me ta men aramas akan karos me kadeik ki ong mela, i dueta pung ta ieu itar ong kapung kila aramas akan karos, en kamaurela.',
        19: 'Pwe duen sopeik en aramas ta men me toto wia kilar dipan, iduen peik en me ta men me toto pung kilar.',
        20: 'A kapung pil wiauier, pwe dip en kadiarok kidar, a wasa me dip paraparada ia, iei wasa mak o laude sanger.',
        21: 'Pwe duen dip dialang mela, iduen mak o pung pan dialang maur soutuk ki Iesus Kristus atail Kaun.',
    },
    6: {
        1: 'ARI, da me kitail en inda? Kitail en dadaurata dip, pwe mak en lalaudala?',
        2: 'O so! Pala kitail pan dadaurata dip, me kitail mela sanger?',
        3: 'De komail sota asa, me karos, me paptaise ong Kristus Iesus, paptaise ong a matala?',
        4: 'Kitail ari iang i saredier ni paptais ong mela, pwe duen Kristus kaiasa kidar lingan en Sam sang ren me melar akan, iduen kitail en pil weweideki ni maur kap.',
        5: 'Pwe ma kitail kaparoki ong i ni a matala, nan kitail pil pan paroki ong i ni a iasadar.',
        6: 'Pwe kitail asaer, me atail aramas maring iang kalopuelar, pwe war en dip en mokonaidier, pwe kitail solar papa dip.',
        7: 'Pwe me melar, maiodar sang dip.',
        8: 'A ma kitail iang Kristus matalar, nan kitail kamelele, me kitail pil pan iang i ieiasata.',
        9: 'Kitail asa, me Kristus kotin iasadar sang ren me melar akan, ap solar pan pur ong matala; mela solar pan poedi i.',
        10: 'Pwe ni a kotin matalar, a kotin matalar pan metapak pweki dip, a ni a kotin ieiasata, a kotin ieiasadang Kot.',
        11: 'Iduen komail, komail en wia kin komail me melar sang dip, ap memaur ong Kot ren Kristus Iesus.',
        12: 'Ari, komail ender mueid ong dip, en kaunda war omail luet; pwen papa a inong sued akan.',
        13: 'Komail pil der mueid ong dip o kokon omail akan, pwen men wia sapung a komail mueid ong Kot pein komail, duen me kamauradar sang ren me melar akan, o kokon omail akan en papa me pung ong Kot.',
        14: 'Pwe dip sota pan kak poe komail edi, pwe komail solar mi pan kapung, pwe pan mak.',
        15: 'Ari da, kitail en wia dip, pwe kitail solar mi pan kapung, a pan mak? O so!',
        16: 'Komail sota asa, ma komail pan wiala pein komail ladu en peik, ari komail pan ladu en me komail kin pepeiki ong? Ma dip komail pan mekila, a ma peik, komail pan pung kida.',
        17: 'A danke ong Kot pwe komail solar ladu en dip; pwe met komail kin peiki ong tiak en padak me komail ianger sang mongiong omail.',
        18: 'Komail ari maioda sang dip, komail id wiala ladun pung.',
        19: 'Ngai me inda met nin tiak en aramas, pweki luet en uduk omail. Pwe duen omail pangalang kokon omail akan, en ladun samin o sapung kan, pwen palian kapung, iduen komail en pang ong kokon omail, en lidui me pung, pwen sarauila.',
        20: 'Pwe ni ansau me komail ladun dip, komail maio sang me pung.',
        21: 'A iaduen wan mepukat ni ansau o, me komail kin namenokki ansau wet? Pwe imwi pan mepukat mela.',
        22: 'A met komail maiodar sang ni dip, ap id wialar ladun Kot, o omail wan saraui mia o imwi pan maur soutuk.',
        23: 'Pwe pwain en dip mela, a pai en mak en Kot maur soutuk ren Kristus Iesus atail Kaun.',
    },
    7: {
        1: 'DE ri ai kan, komail sota asa — i kin peidok ren me asa kapung o — me kapung o kin poedi aramas arain a memaur?',
        2: 'Pwe li amen, me a warok mia, kin kaupingki kapung en a warok arain a memaur. A ma a warok melar, a muei sanger kapung en a warok.',
        3: 'A ma a pan paudeki amen ol ni a warok memaur, a pan adaneki kamal amen; a ma a warok melar, a muei sanger kapung, ap sota pan kamal amen, ma a pan pur ong amen ol.',
        4: 'Ari ri ai kan, iduen pil komail mekilar kapung o pweki war en Kristus, pwen wiala nain amen, iet, me iasadar sang ren me melar akan, pwen kaparapar ong Kot.',
        5: 'Pwe ni at kekeideki tiak en pali uduk, inong en dip me kelail nan kokon atail pweki kapung o, pwen kaparapar ong mela.',
        6: 'A met kitail muei sanger kapung o, pwe sal pat ong mela olar, pwe kitail en papa ong tiak kap en ngen, a kaidin ong tiak maring en inting.',
        7: 'Ari, da me kitail en inda? Me dip kapung o? O so! A i pan sasa dip, ma so kapung. Pwe i pan sasa duen inong sued, ma kapung so kalok kidar: Koe der norok!',
        8: 'A dip kadiarok kidar kusoned, ap kainong ong ia song en inong sued karos, pwe ma sota kapung dip mela.',
        9: 'Pwe mas o i sota mi pan kapung, ap mamaureta, a kusoned lao mia, dip ai ap diarokadar.',
        10: 'A ngai melar; kusoned, me loki dong ia, pwe i en maure kida, kare ong ia mela.',
        11: 'Pwe dip kadiarok kidar kusoned liapai ia dar, ap kame ia lar.',
        12: 'Ari, kapung o me saraui o kusoned me saraui, a pung o mau.',
        13: 'A iaduen me mau kot kare ong ia mela? O so! A dip en sansale kida me kamau o ni a kare ong ia mela, pwe dip en sansale kida kusoned.',
        14: 'Pwe kitail asa, me kapung o me ngenin, a ngai me uduken o netilang dip.',
        15: 'Pwe i sota asa, da me i en wia. Pwe kaidin me i mauki, me i kin wiada, a me i kin suedeki, iei me i kin wia.',
        16: 'Ari, ma i kin wiada, me i kang wia, nan i kin kasansaleda, me kapung me mau.',
        17: 'A ma i wiadar, me i sota men wia, kaidin ngai me wiadar, a dip me mimi lol i.',
        18: 'Pwe i asa, me sota mau kot mi lol i nan uduk ai, pwe i kin men wiada me mau, a en angada me pung i sota kak ong.',
        19: 'Pwe me mau o, me i men wiada, i sota kin kapwaida, a me sued, me i kang, i me i kin wiada.',
        20: 'A ma i wiada, me i so men wiada, kaidin ngai me wiada, a dip me mi lol i.',
        21: 'Iet me kapung kadiarok ong ia: Ni ai men wiada me mau, me sued mimi re i.',
        22: 'Pwe i kin mauki kapung en Kot pali lol en aramas.',
        23: 'I ap diaradar eu kapung ni ai kokon akan, me kin palian kapung en loli, ap kalua ia di pan kapung en dip, me mi nan ai kokon akan.',
        24: 'O ngai aramas luet amen! Is me pan kamaio wei ia sang ni war mela wet!',
        25: 'I danke Kot pweki Iesus Kristus atail Kaun. Nan lol i i kin papang kapung en Kot, a ni pali uduk kapung en dip.',
    },
    8: {
        1: 'ARI, solar me mau ong pakadeikada, me mi ren Kristus Iesus.',
        2: 'Pwe kapung en Ngen en maur ren Kristus Iesus kamaio ia da sang ni kapung en dip o mela.',
        3: 'Pwe me kapung sota kak ong, aki a luete kila pali uduk, iei me Kot kotin wiada ni a kotin poronedo sapwilim a Ol ni mom en uduk en dip, pweki dip, pwen kadeikada dip ni pali uduk.',
        4: 'Pwen kapwaiada pung en kapung re atail, me sota weideki pali uduk a pali Ngen.',
        5: 'Pwe me kisan pali uduk, kin lamelame duen inong en uduk, a me kisan pali Ngen, kin lamelame duen inong en Ngen.',
        6: 'Pwe tiak en uduk iei mela, a tiak en Ngen maur o popol.',
        7: 'Pweki tiak en uduk kin palian Kot, pwe a sota kin duki ong kapung en Kot, pwe a pil sota kak ong.',
        8: 'A me kisan pali uduk, sota kak konekon ren Kot.',
        9: 'A komail kaidin kisan pali uduk, pwe kisan pali Ngen, ma Ngen en Kot kotikot lol omail. A me sota aneki Ngen en Kristus, i kaidin sapwilim a.',
        10: 'A ma Kristus kotikot lol omail, war mekilar dip, a ngen memaureki pung.',
        11: 'A ma Ngen o, me kaiasadar Iesus sang ren me melar akan, kotikot lol omail, nan i me kaiasadar Kristus sang ren me melar akan, pil pan kamaureda war omail mela ki Ngen e, me kotikot lol omail.',
        12: 'Ari ri ai kan, kitail solar pwaipwand ong pali uduk, pwen kapwaiada inong en uduk,',
        13: 'Pwe ma komail memaureki uduk, komail pan mela, a ma komail pan kamela wiawia en pali war ki Ngen, komail pan memaureta.',
        14: 'Pwe karos me weweideki Ngen en Kot, nan irail seri en Kot akan.',
        15: 'Pwe kaidin ngen en ladu, me komail aleer, pwen pur ong masak, a Ngen en seri, me komail aleer, me kitail kin eker kida: Apa, Sam!',
        16: 'Pein ngen o kotin iang ngen atail kadedeki, me kitail seri en Kot akan.',
        17: 'A ma kitail seri kan, nan kitail pil seri en soso, seri en soso en Kot o kisan toun soso en Kristus, ma kitail iang kamekam, kitail pil pan iang linganla.',
        18: 'Pwe i asaer, me kamekam en ansau et sota mau ong en kaparoki ong lingan kokodo, me pan kasansaledang kitail,',
        19: 'Pwe audepan sappa poden anane kaualap papasan en seri en Kot ar pan maioda.',
        20: 'Pwe audepan sappa o pangalang mela, kaidin pweki pein insen arail, a pweki i, me pang ir alang kaporopor.',
        21: 'Pwe audepan o pil pan maioda sang ni a lidulidui ong tiak en soredi, ong maio en lingan en seri en Kot akan.',
        22: 'Pwe kitail asaer, me audepan sappa karos kin sangesanglol o mimi pan wairok en naitik lao lel met.',
        23: 'A kaidin irail eta, pwe kitail pil iang, me mesenin Ngen, pil pein kitail kin sangesang, auiaui lao ansau en pali war atail ar kawilikapada.',
        24: 'Pwe kitail kamaurelanger kaporopor. A kaporopor me sansal, i kaidin kaporopor; pwe me amen kin ududial, menda en kaporoporeki?',
        25: 'A ma kitail kaporoporeki, me kitail sota udial, kitail kin kanongama auiauieta.',
        26: 'Pil Ngen o kotin sauasa kitail ni atail luet akan, pwe kitail sasa, da me kitail en poeki, o da me kon ong, pwe pein Ngen o sangesangelol o laolao kin kitail.',
        27: 'A me kin kotin kasauiada mongiong akan, mangi duen kupur en Ngen, pwe a kin kotin laolaoki saraui kan duen tiak en kupur en Kot.',
        28: 'A kitail asa, me karos kin kamauiala me pok ong Kot akan, irail me paeker duen ar kileledier.',
        29: 'Pwe me a kotin piladar mas o, iei me a pil kotin kileledier, en tialang mom en sapwilim a Ol, pwe a en meseni nan pung en ri a kan.',
        30: 'A me a kotin kileledier mas o, a pil kotin waronge irail edo, a me a kotin warongedor, a pil kapung irail alar, a me a kapungalar, a pil kotin kalingan irail adar.',
        31: 'Ari, da me kitail en sapenki mepukat? Ma Kot iang kitail, is me pan kak palian kitail?',
        32: 'I me sota kotin kasampwaleki sapwilim a Ol, pwe a kotiki wei en wiliandi kitail, dadue, a so pan kotin sapan iangaki dong kitail meakaros?',
        33: 'Is me pan kapung ong en Kot a piladar akan? Pwe Kot eta, me kotin kapungada;',
        34: 'Is me pan kadeikada? Pwe Kristus me matalar, me pil kaiasada o me pil kaipokedi ni pali maun en Kot, o me pil kin laolao kin kitail.',
        35: 'Is me pan irawei sang kitail ni limpok en Kristus? Ansau apwal, de masak, de kamekam, de isesol, de kiliso, de kamasak, de kodlas?',
        36: 'Duen a intingidier: Pweki komui kit kamekame kilar kaukaule, kit me wadok ong sip akan, me kileledier ong kamela.',
        37: 'A ni mepukat karos kitail me poedier kaualap pweki i, me pok ong kitail er.',
        38: 'Pwe i asa, me kaidin mela, de maur, pil kaidin tounlang kan, de saupeidi, pil kaidin men met, de men mur, de me manaman akan,',
        39: 'Pil kaidin men poe, de men pa, de okotme pan kak irawei sang kitail ni limpok en Kot, me mi ren Kristus Iesus atail Kaun.',
    },
    9: {
        1: 'NGAI kin lokaia melel ren Kristus, o i sota kin likam, pwe insen ai o Ngen saraui kadede ia da,',
        2: 'Me i kin patautau o insensued nan mongiong i kaukaule.',
        3: 'Pwe pein ngai inong iong en riala, pwen dooki wei sang Kristus pweki ri ai kan ni pali uduk.',
        4: 'Iei men Israel me udan seri en Kot, me ar lingan, o inau kan, o kapung, o upa Kot, o kokop akan mia,',
        5: 'Me samaneki sam atail akan me Kristus pil tapi sang ia ni pali uduk a, me poedi meakaros, iei Kot me iasanai kokolata, amen.',
        6: 'Pwe kaidin dene masan en Kot so pwaida, pwe kaidin karos men Israel, me tikidar Israel;',
        7: 'Pil kaidin karos seri kan, me kisan kadaudok en Apraam; pwe sang ren Isaak kadaudok om pan tapi sang ia.',
        8: 'Ari, kaidin irail seri en Kot akan, me seri kan ni tiak en uduk, a seri en inau kan pan wad ong kadaudok o.',
        9: 'Pwe i masan, masan en inau eu: Ni ansau o I pan kodo, a Sara pan naitikada seri ol amen.',
        10: 'A kaidin i eta, pwe pil Repeka lao lisean ong sam atail Isaak.',
        11: 'Pwe ni ansau seri ko kaikenta ipwidier, o pil kaikenta wiadar meakot mau de me sued, o pwe kupur en Kot en pwaida, kaidin ni wiawia a ni lipilipil ren me piladar o,',
        12: 'A kotin masani ong i: Me laud o pan papa me tikitik!',
        13: 'Duen a intingidier: Iakop me I pok ong er, a Esau me I likidmalielar.',
        14: 'Ari, da me kitail en inda? Kot me sapung? O so!',
        15: 'Pwe a kotin masani ong Moses: I pan maki ong, me I men maki ong, o I pan pokepoke, me I men pokepoke.',
        16: 'Ari, sota katepa, ma amen pan pein inong iong de tange wei, a ma Kot pan kotin maki ong amen.',
        17: 'Pwe kisin likau me katitiki ong Parao: Nan iet me I kilele uk adar, pwe I en kasale kida uk ai manaman, o pwe mar ai en indandeki sili ni sap akan karos.',
        18: 'Ari, a kin kotin maki ong, me a kotin kupura, ap kapitakaila, duen me a kotin mauki.',
        19: 'Koe ap pan indang ia: Ari da me a kailong kin ia? Pwe is me kak palian kupur a?',
        20: 'Ei melel aramas koe, is koe, me men palian Kot? Da, dipisou pan indai ong me wiadar i: Menda koe wiai ong ia momuei?',
        21: 'Pala saun wiada dal sota manaman ong, en wia kida lopon en pwel ota dal eu me kaselel, de eu me sakanekan?',
        22: 'A Kot kotin kanongama ong dal sued akan, me wiauier ong lokidokila, ni a men kasaleda a ongiong o manaman,',
        23: 'O a pil men kotin kasaleda a dir en lingan ki dal en a mak kan, me a kotin kaonopadar mas o en linganla.',
        24: 'Iei kitail, me a kotin warongdo, kaidin sang ren Sus akan eta, a pil sang ren men liki kan.',
        25: 'Duen a pil kotin masanier nan puk en Osea: I pan kaadaneki irail, me kaidin nai, nai aramas akan, o me so kompoke pai, kompoke pai.',
        26: 'A pan wiaui wasa o me a loki ong irail: Komail kaidin nai aramas, i wasa re pan adaneki seri en Kot ieias.',
        27: 'A Iesaia likelikwir duen men Israel: Ma seri en Israel akan pan rasong pik en oror, lua ta pan maurela.',
        28: 'Pwe a pan kotin kairela sapwilim a dodok o kamode kila ni a pung, pwe Kaun o pan kotin wiada dok motomot nin sappa.',
        29: 'O duen Iesaia masanier mas o: Ma Kaun Sepaot so nikideki ong kitail kaparapar, kitail pan dueta Sodom o Komora.',
        30: 'Ari, da me kitail en inda duen men liki kan me sota rapaki pung, re diaradar pung, a pung eu, me tapi sang poson.',
        31: 'A men Israel me inong iong kapwaiada kusoned en pung, ap sota konodi kusoned wet.',
        32: 'Pwekida? Pweki a sota tapi sang ni poson a ni wiawia kan, pwe irail dipikelekeleki takai en dipikelekel.',
        33: 'Duen a intingidier: Kilang, I pasonedi takai eu nan Sion, takai en dipikelekel eu o paip en kamakar. A me pan poson i, a sota pan sarodi.',
    },
    10: {
        1: 'RI ai kan, inong en mongiong i, o ai ngidingid kin irail ong Kot pan dore ir ala.',
        2: 'Pwe ngai kadede parail, me re kin nantiong Kot, ap sasa tiak.',
        3: 'Pwe re sasa pung en Kot, ap sosong kapwaiada pein arail pung, ap sota duki ong pung en Kot.',
        4: 'Pwe Kristus kaimwisok pan kapung o; karos me poson en pung kila.',
        5: 'Pwe Moses masanier duen pung en me pwili sang kapung o: Aramas o, me kapwaiada song pukat, a pan maur kila.',
        6: 'A iet me pung, me pwili sang poson, kin inda: Der inda nan mongiong om: Is me pan daudala nanlang? Iet wewe: En wadido Kristus.',
        7: 'De is me pan daudi wasa lol? Iet wewe: En wadado Kristus sang ren me melar akan.',
        8: 'A da me a kin inda? Masan o me koren iong uk, a kin mi nan au om o nan mongiong om; iei masan en poson, me se kin padaki wei.',
        9: 'Pwe ma koe pan kadedeki au om Iesus, me i me Kaun, ap poson nan mongiong om, me Kot kotin kaiasadar i sang ren me melar akan, koe ap pan doro kila.',
        10: 'Pwe poson kin tapi sang nan mongiong o, pwen pung kila, o kadede kin tapi sang nan au o, pwen maur kila.',
        11: 'Pwe kisin likau me masani: Amen amen me pan poson i, sota pan soredi.',
        12: 'Pwe sota irair eu nan pung en men Sus o men Krik, pwe Kaun en irail karos me ta men, me dir en kalangan ong karos, me kin likwir ong i;',
        13: 'Pwe amen amen me likwir ong mar en Kaun o pan dore kila.',
        14: 'A iaduen, irail pan likwirlang i, me irail sota poson? A iaduen, irail pan kak poson i, me re saikenta rong? A iaduen irail pan kak rong, ma sota saunpadak?',
        15: 'A iaduen, irail pan kak padaki wei, ma re sota pan pakadarala? Duen a intingidier: Meid pai nä en me padaki rongamau en popol, me padaki rongamau en me mau kan!',
        16: 'A kaidin karos me peiki ong rongamau. Pwe Iesaia masani: Maing, is me kamelele at padak?',
        17: 'Ari, poson kin pwili sang padak, a padak kin pwili sang masan en Kot.',
        18: 'A ngai me inda: Irail sota rongadar? O ei! Pwe ngil arail leler sap karos, o ar padak lel ong irair en sappa.',
        19: 'A ngai me inda: Israel sota wewekier? Pwe iet kaieu, me Moses masani: I pan kasarowei kin komail, me kaidin nai aramas, o I pan kamakara kin komail aramas pweipwei kan.',
        20: 'A Iesaia kelail masani: Ngai me kadiarokada sang ren me sota rapa kin ia, o Ngai me pwara dong, me sota idok ia.',
        21: 'A kotin masani duen Israel: Kaukaule I kapawei pa i kat ong aramas katiwo o kangudi kan.',
    },
    11: {
        1: 'ARI, iet me i men inda: Kot kalikalar sapwilim a kan? O so! Pwe ngai pil kisan men Israel, o kadaudok en Apraam, o kainok en Peniamin.',
        2: 'Kot sota kalikalar sapwilim a kan, me a kotin piladar mas o. De komail sota asa, da me kisin likau masanier duen Elias ni a kadipa men Israel mon Kot masani:',
        3: 'Maing, irail kamelar sapwilim ar saukop akan, o karongk pasang sapwilim ar pei saraui kan, a ngai ta me lua, a irail pil rapakin ia, pwen kame ia la.',
        4: 'A da me Kot kotin sapengki i? Ngai me kanikidi ong ia ol isikid me so kelepuki ong Paal.',
        5: 'Nan iduen ansau wet: Luan me piladar akan mia pweki mak en Kot.',
        6: 'A ma pweki mak, nan kaidin pweki wiawia kan; pwe ma iduen, mak solar pan mak.',
        7: 'Ari, iaduen mepukat? Me men Israel raparapaki, re sota diaradar, a me piladar akan diaradar, a me tei kan kapitakailar.',
        8: 'Duen a intingidier: Kot kotiki ong irail ngen en men mair, o por en mas akan, pwe ren der kilang wasa, o salong akan, pwe ren der rong wasa lao lel ran wet.',
        9: 'O Dawid masani: Arail tepel en wiala insar parail, o litip arail, o kapup parail, o karia parail.',
        10: 'Mas arail en rotorotala, pwe ren der kilang wasa, o irail en kakos pena kokolata.',
        11: 'Ari, iet me i men inda: Irail dipikelekel pwen pupedi? O so! A pweki arail pupedi, en id kamaurela men liki kan, pwen kapopot kin irail do.',
        12: 'Ari, ma arail pupedi id pai ong sappa, a arail momalar id pai ong men liki kan, ia wan pai, ma irail karos pan sapaledo!',
        13: 'Pwe men liki komail, me i men padaki ong, pwe ngai wanporon en men liki kan, i men kaindinda ai dodok.',
        14: 'Pwe ma i kak ong, i pan kainong irail, me kit eu ni pali uduk pwe akai re’rail en dorela.',
        15: 'Pwe ma arail kalikilar id kalamalam maula sappa, arail kasapaledo so pan kamaurela sang ren me melar akan?',
        16: 'A ma kalap me saraui, plaua amas pil pan saraui; o ma kalaua me saraui, ra kan pil pan dueta;',
        17: 'A ma ra kai tapengok sang, a koe ni om wos mal id peus iong, ap iang nim pil en tuka o iang maurki kalaua,',
        18: 'Koe ap der suaiki ong ra kan! A ma koe suaiki ong irail, kaidin koe me kin wa kalaua, a kalaua kin wa uk.',
        19: 'Koe ap pan indada: Ra kan tapengok wei sang, pwe i en id peus ong.',
        20: 'Me pung; soposon, me re tapengok kilar, a poson, me koe maur kila, koe der aklapalap a masak!',
        21: 'Pwe ma Kot kotin muei sang udan ra kan, kalaka, pwe ele a pil pan muei sang uk!',
        22: 'Ari, kilang kalangan o ongiong en Kot; ongiong ong irail, me salongalar, a kalangan ong uk, ma koe pan dadaurata a kalangan, a ma so, koe pil pan tapengok sang.',
        23: 'A pil irail, ma irail sota pan mimieta ni arail soposon, re ap pan peus sapal, pwe Kot kotin kak ong kapure irail do.',
        24: 'Pwe ma koe lepuk sang ni tuka olip mal, ap peus sapal ong tuka olip mau, a iaduen udan ra mau kan, re sota pan kak pur ong udan ar tuka?',
        25: 'Ri ai kan, i men, komail en lelapok ki kaponepon wet, pwe komail de aklolekong, duen apali en Israel me kapitakailar, lao lel ansaun irail me pilipildar ren men liki kan pwarador.',
        26: 'Men Israel karos ap pan maureda, duen a intingidier: Amen pan kotido sang Sion, me pan kawela karos me doo sang Kot akan ren Iakop.',
        27: 'Pwe iet ai inau ong irail, i lao lapwa sang irail dip arail akan.',
        28: 'Iran rongamau irail me imwintiti pweki komail, a iran lipilipil irail me kompokepa kan pweki sam akan.',
        29: 'Pwe Kot sota kin kalukila a pai en mak akan de me a kotin piladar.',
        30: 'O duen komail, me pil sota poson Kot mas o, a met komail aleer mak, pweki arail soposon.',
        31: 'Iduen irail me sota poson mak, me komail diaradar, iei me re pil sota diaradar mak en Kot.',
        32: 'Pwe Kot me kotin kapata pena irail karos ni soposon, pwen mak pena ong karos.',
        33: 'O meid laud erpit en Kot o a kotin mangi meakaros, sota me kak weweki a kadeik kan, de pameda al en a wiawia kan!',
        34: 'Pwe is me asaer kupur en Kaun o, de is me padaki ong i meakot?',
        35: 'De is me ki ong i meakot, pwen depuk ong i?',
        36: 'Pwe meakaros tapi sang re a, o mia pweki i, o wiai ong i, lingan en ko ong i kokolata! Amen.',
    },
    12: {
        1: 'RI ai kan, i ap panaui komail pweki kalangan en Kot, komail en kida war omail, pwen wiala mairong maur, me saraui o kaperenda kupur en Kot, iei omail kaudok me pung.',
        2: 'Komail der kaalemongin sappa, a komail en kawilikapada lol omail, pwe komail en kak kasauiada, da me kupur en Kot, me mau o kaperen, o unsok.',
        3: 'Ki mak, me i aleer, i indang amen amen nan pung omail, ender inong iong pein i, laude sang me kon ong, a en lamelame me a en pung, duen Kot kotin nek ong amen amen wan a poson.',
        4: 'Pwe duen ni pali war atail kokon toto mia, a dodok en kokon akan kaidin dupeneta,',
        5: 'Iduen kitail me toto, war ta ieu ren Kristus, kitail ap kokon pena nan pung atail.',
        6: 'Atail pai en mak akan mia ap toror pasang, duen mak o me kitail aleer: Ma deideikop kitail en kokopada duen wan poson,',
        7: 'O ma dodok eu, kitail en kolekol atail dodok; o ma saunpadak amen, i en wiada padak,',
        8: 'Ma amen kin panaui, i en panaui, ma amen kin kisakis wei, a en opampap, ma kaun amen, a en kanekanaiong, ma amen, kin kalangan, a en peren kida.',
        9: 'Omail limpok ender sapung, tateki me sued, tengeteng ni me mau.',
        10: 'Omail limpok pena en tapi sang mongiong omail; wauneki amen, mon a pan waune kin uk.',
        11: 'Der tanganga ni omail dodok; ngen omail en inong iong dodok ong Kaun o.',
        12: 'Peren ni kaporopor; kanongama ni ansau apwal; podidi ong kapakap.',
        13: 'Kisakis ong saraui samama kan; kasamo ki peren.',
        14: 'Kapaiada me kin paki komail; kapaiada o der kariala.',
        15: 'Perenda ren me popol akan; o sangesang ren me sangesang kan.',
        16: 'Komail minimin pena ni omail lamelam, der inong iong meakot me lapalap, a inong iong me tikitik; komail der aklolikong.',
        17: 'Komail der depukki ong en amen a me sued me sued, a inong iong me kon ong aramas akan karos.',
        18: 'Ma a pan kak pa omail, polaul ong aramas akan karos.',
        19: 'Kompoke pai ko, komail der pein depuk, o komail der madang makar, pwe a intingidier: Ai depuk, Ngai me pan depuk, me Kaun o kotin masani.',
        20: 'Ari, ma om imwintiti amen men mangadar, kamanga i; ma a men nim piladar, kanim pileda, pwe ma koe pan wia mepukat, nan koe ap pan ki penang mong a kol molus.',
        21: 'Koe der lodi ong me sued, a poekidi me sued me mau.',
    },
    13: {
        1: 'AMEN amen en upa kaun akan, me kin poe irail edi, pwe sota kaun akan me sota sang ren Kot, a wasa kaun akan mia, nan irail me ren Kot.',
        2: 'Ari, me pan katiwo ong kaun akan kin katiwo ong kusoned en Kot, a me katiwo kan, pan lodi ong kapung.',
        3: 'Pwe saupeidi kan sota kin kamasakki, me kin wia mau, pwe me kin wia me sued. A ma koe sota men masak kaun akan, en wiada me mau, koe ap pan indandeki pa’rail.',
        4: 'Pwe a papan Kot o iei me mau ong uk, a ma koe wia me sued, masak, pwe a sota kin wa mal kodlas. Pwe a papan Kot o, pwen kame me wia sued.',
        5: 'Iei me komail en peiki ong, a kaidin pweki kamekam a pweki insen omail.',
        6: 'Iei me komail pil wiai ong nopwei, pwe irail me papan Kot, me kin kaukaule papa wet.',
        7: 'Komail ari kapungala omail pwaipwand ong amen amen! Taksis ong me taksis kin wiaui ong, nopwei ong me nopwei kin wiaui ong; masak, me masak kin ko ong; ki ong wau, me wau kin ko ong.',
        8: 'Der pwaipwandeki meakot ong amen; iet eta: Omail limpok pena, pwe me kin pok ong amen, kin kapwaiada kapung o.',
        9: 'Pwe iet akan: Koe der kamal! Koe der kamela aramas! Koe der pirap! Koe der norok! O ma pil eu kusoned mia, iet orlepa: Koe en pok ong men imp om due pein uk!',
        10: 'Limpok sota kin wia sued ong men imp a. Ari, limpok audepan kapung.',
        11: 'O pil met: Kitail en dedeki duen ansau o, pwe auer leler, me kitail en pirida sang mair, pwe ansaun atail dorela me koren sang ni tapin atail poson.',
        12: 'Pongpong daulier, a ran me korendor. Kitail en pwilikidi wiawian rotorot akan, ap ale tatan marain.',
        13: 'Kitail en kekeid ni tiak mau, pwe ni ran; der kaped en manga de kamom soko, der samin de saut, de luak, de peirin.',
        14: 'A komail ale Kaun Iesus Kristus, o der kangongala pali uduk, pwen angeda a inong sued.',
    },
    14: {
        1: 'KOMAIL apwali me luet ni poson o der kaping irail ada.',
        2: 'Amen kin lamelame, en kangkang song karos, a me luet kin kangkang wan tuka.',
        3: 'Meamen me kin kangkang, ender mamaleki, me sota kin kang; o me so kin kangkang, ender kadeikada me kin kang, pwe Kot kin apapwali i.',
        4: 'Pwe is koe, me kin kadeikada en amen a ladu, pwe ma a pan uda de pupedi a pan nain a saumas eta. Melel, a pan pil uda, pwe Kaun o me kotin kak ong kauada i.',
        5: 'Amen kin pilada a ran kasampwal mon me tei kan, a amen ran karos dupeneta re a; a amen amen en pung ni a lamelame.',
        6: 'Meamen me moaki ran eu, Kaun o me a moaki ong, me kin manga, Kaun o me a manga ong, pwe a kin dangke Kot, o me sota manga, nan Kaun o me a so manga ong, ap kin danke Kot.',
        7: 'Pwe sota meamen re’tail kin memaur iong pein i, o sota me kin mela ong pein i.',
        8: 'Pwe ma kitail memaur, Kaun o me kitail kin memaur iong, o kitail mela, Kaun o me kitail pan mela ong, ari, kitail memaur de mela, sapwilim en Kaun o kitail.',
        9: 'Pwe i me Kristus matalar ap iasadar, pwen kaunda me melar o memaur akan.',
        10: 'Ari, menda koe kin kadeikada ri om? De koe, menda koe mamaleki ri om? Pwe kitail karos pan wisikelang mol en kadeik en Kot;',
        11: 'Pwe a intingidier: Kaun o kaukila pein i masani: Nä karos pan kelepuki ong ia, o lo karos kadede Kot.',
        12: 'Nan i kitail karos pan weokada pein kitail ong Kot.',
        13: 'Kitail ari ender kadeikada amen amen; a mak eta, kitail en kadeikada iet akan, ender ki ong ri atail kasasepa de men kamakar.',
        14: 'Ngai me lamedar o asadar pan Kaun Iesus, me sota okotme me udan samin; a meamen, me kasamineki meakot, nan i me samin ong.',
        15: 'Pwe ma ri om pan insensuedeki om kisin manga, koe sota kin weweid nin tiak en limpok; ender kawe kila om manga i, me Kristus mata kilar.',
        16: 'Komail ari kalaka, pwe omail wiawia mau de kalok sued:',
        17: 'Pwe wein Kot kaidin manga o nim, a pung, o popol, o peren ren Ngen saraui.',
        18: 'Pwe me kin papa Kristus ni mepukat, i me pung ren Kot o pil konekon ren aramas akan.',
        19: 'Kitail ari en inong iong meakan, me kin kareda popol o kamakamaui kitail pena amen amen.',
        20: 'Koe ender kawe kila kisin manga wiawia en Kot. Ari, karos me min, ap sued ong aramas amen, me luet ap mangamanga.',
        21: 'Me mau, koe ender kang uduk de nim wain, de wia meakot, me ri om ol pan pupe kidi, de makaraki, de kaluete kila.',
        22: 'A ma om poson mia ni mepukat, ari kamaui pein uk mon Kot. Meid pai, me sota kin kadeikada pein i ki meakan, me a kin kasampwaleki.',
        23: 'A meamen, me peikasal ap manga, me pakadeikadar, pwe a sota tapi sang poson. A karos me sota kin tapi sang poson, iei dip.',
    },
    15: {
        1: 'A MAK eta, kitail kelail akan, en sauasa me luet akan, ap der peren ki pein kitail.',
        2: 'Amen amen kitail en pok ong men impa, pwen kamauiala i.',
        3: 'Pwe Kristus pil sota kin pok ong pein i, a duen intingidier: Pakainak en me kainaki komui, me I dikidier raui.',
        4: 'Pwe karos me intingidier mas o, me intingidier, pwen padaki dong kitail, pweki kanongama o kamait en kisin likau kan kitail en kaporopor.',
        5: 'Ari, Kot en kanongama o kamait en kaminimin komail pena duen Kristus Iesus.',
        6: 'Pwe komail en kalinganada Kot o Sam en atail Kaun Iesus Kristus ni lamalam ta pot o au ta ieu.',
        7: 'I me komail en apapwali pena dueta Kristus me kotin kasamo komail ong lingan en Kot.',
        8: 'Pwe ngai inda, me Iesus Kristus wialar papan sirkomsais pweki melel en Kot, pwen kapwaiada inau kan ong sam akan.',
        9: 'Pwe men liki kan en kalinganada Kot pweki a mak duen a intingidier: I me I pan kadededa komui ren men liki kan o kauleki mar omui.',
        10: 'O pil eu me a kotin masani: En popol komail men liki kan iangaki sapwilim a aramas!',
        11: 'O pil eu: Kapinga Kaun o, komail men liki kan karos o kalinganada i, komail wei karos!',
        12: 'O pil eu me Iesaia masani: Ip en Iese pan pwarado, a pan pwarado, pwen kaunda men liki kan, i me men liki kan pan kaporoporeki.',
        13: 'Ari, Kot en kaporopor en kadire kin komail peren o popol karos ni poson, pwe omail kaporopor en laudeki manaman en Ngen saraui.',
        14: 'A ngai asa mau duen komail ri ai kan, me komail dir en kamau o audaudeki erpit, o koiokki ong panapanaui pena amen amen.',
        15: 'Ari so, ri ai kan, i inting wong komail er duen met, pwen kataman kin komail mak eu, me Kot kotiki ong ia er.',
        16: 'Pwe i en papan Kristus Iesus ong men liki kan, padapadaki wong ir rongamau en Kot, pwe men liki en wiala mairong eu, me konekon, me kasaraui kila Ngen saraui.',
        17: 'I me i kak suaiki pan Kristus Iesus pweki meakan me sapwilim en Kot.',
        18: 'Pwe i sota pori ong inda meakot, me Kristus sota kotiki ong ia, i en kalua men liki ong peik, ki ai padak o wiawia kan.',
        19: 'O kilel o manaman akan, en Ngen saraui. Ari, i me i kadire kila rongamau en Kristus sap karos, tapiada Ierusalem, ap lel ong Ilirien.',
        20: 'Ngai nantiong ni ai padaki rongamau wasa me saikenta asa duen Kristus pwe i de kauada pon pason en amen.',
        21: 'A duen a intingidier: Me saik kalok ong irail pan kilang, o me sota rong, re pan weweki.',
        22: 'Nan i me karompwa ia pan pak toto, pwen sota kak pwar wong komail.',
        23: 'A met solar wasan dodok ni sap pukat, a par toto me i inong iong en pas wong komail.',
        24: 'I lao sailokelang Spanien, i pan pwar wong komail, pwe i kaporoporeki, me i pan sup wasa o ap kilang komail, a komail pan kalua ia lang wasa o murin ai kaserloleit re omail.',
        25: 'A met i pan sailokelang Ierusalem, pwen papa saraui kan.',
        26: 'Pwe men Masetonien o Akaia kan mauki kisakisa wei ong saraui samama kan, me mi Ierusalem.',
        27: 'Irail mauki pwe re pil pwaipwand ong irail, pwe ma men liki kan pwaisanekier arail pai ngenin, nan me kon ong, irail en pakisakis dong irail ar pai pali war.',
        28: 'I lao kapwaiadar mepukat o ki ong irail er kisakis sapan wet, i ap pan sup re omail o daululang Spanien.',
        29: 'A i asadar, i lao pwaralang komail, i pan dir pai ki en Kristus.',
        30: 'A ri ai kan, i ap poeki komail pan atail Kaun Iesus Kristus o limpok en Ngen pwe komail en dauki pena ong ia omail kapakap kin ia ong Kot.',
        31: 'Pwe i en piti sang men Iudäa soposon akan, o pwe ai dodok ong Ierusalem en sauasa saraui kan.',
        32: 'Pwe i en perenki lel ong komail pan kupur en Kot o iang komail tapwenda.',
        33: 'Ari, Kot en popol en kotikot re omail karos! Amen.',
    },
    16: {
        1: 'I ap kakaliki ong komail ri atail li Pepe, me kin papan momodisou en Kenkrea,',
        2: 'Pwe komail en kasamo i pan Kaun duen me kon ong saraui kan, o komail sauasa i ni meakaros, pwe i me sauas pan me toto o pil ngai.',
        3: 'Ai ranamau ong Prisila o Akwila, me sauas pai ren Kristus Iesus.',
        4: 'Me inepai ia da, me kaidin ngai eta, me kin danke ira pwe pil momodisou akan karos nan pung en men liki kan.',
        5: 'Pil momodisou nan im ara. Ranamau ong kompoke pai Epenetus me tapiada momodisou en Kristus nan Asien.',
        6: 'Ranamau ong Maria, me kadek papa kit.',
        7: 'Ranamau ong Andronikus o Iunias, kompoke pai kan o me iang ia salidi, me masamas ren wanporon akan, me sau ong Kristus mo i.',
        8: 'Ranamau ong Aplias, me kompoke pai ren Kaun o.',
        9: 'Ranamau ong Urpan, sauasa pat ren Kristus, o Stakis kompoke pai.',
        10: 'Ranamau ong Apeles, me dadaurata ren Kristus, ranamau ong toun im en Aristopulus.',
        11: 'Ranamau ong Erodion kompoke pai. Ranamau ong toun im en Narsisus, me papa Kaun o.',
        12: 'Ranamau ong Tripäna o Triposa, me papa Kaun o. Ranamau ong kompoke pai Persis, me porisok ni a dodok ong Kaun o.',
        13: 'Ranamau ong Rupus, me pilipildar ren Kaun o o in a pil in ai.',
        14: 'Ranamau ong Asinkritus, Plekon, Ermas, Patropas, Ermes o ri atail akan, me mi re’rail.',
        15: 'Ranamau ong Pilolokus, o Iulia, o Nereus, ri ai li, o Olimpas, o saraui kan karos, mi re’rail.',
        16: 'Komail ranamauki pena metik saraui. Momodisou en Kristus akan kin ranamau ong komail.',
        17: 'Ari, ri ai kan, i panaui komail, komail en kileledi, me kin kamueit pasang o kamakar momodisou palian padak o me komail aleer; komail ari muei sang irail.',
        18: 'Pwe song pukat sota kin papa atail Kaun Iesus Kristus, a pein kaped arail o kotaueki ar kadek lokaia o widing mongiong en me lelapok kan.',
        19: 'Pwe omail peik me indand sili lel penang aramas karos. I me i peren kida komail. A i men, komail en koiokki ong me mau kan, ap sokoiokki ong me sued akan.',
        20: 'A Kot popol pan kasuk pasang Satan pan nä omail eden. Mak en atail Kaun Iesus Kristus en mimieta re omail!',
        21: 'Timoteus ai warok en dodok, o kompoke pai ko Lusius, o Iason, o Sosipater kin ranamau ong komail.',
        22: 'Iet ngai Tertius me intingiedier kisin likau wet, ranamau ong komail pan Kaun o.',
        23: 'Kaius me kin apapwali ia o momodisou, a ranamau ong komail. Erastus, sile pan kanim wet, a ranamau ong komail, o ri atail Kwartus.',
        24: 'Mak en atail Kaun Iesus Kristus en mimieta re omail karos! Amen.',
        25: 'A me manaman ong katinada komail duen ai rongamau, o duen padak iran Iesus Kristus, me kin kasaleda, me sota sansal sang nin tapin kaua kokodo lel met,',
        26: 'A met a sansaledar, pwe kisin likau en saukop akan kaloki ong men liki kan karos duen kusoned en Kot ieias, pwe ren poson o peik;',
        27: 'I Kot eta me erpit, lingan en ko ong i ki Iesus Kristus kokolata! Amen.',
    },
}
